# sitecustomize.py - Força isolamento do .venv_pipeline
import sys
import os

# Caminho base do projeto
_PROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.dirname(__file__)))
_VENV_SITE = os.path.join(_PROJECT_ROOT, ".venv_pipeline", "Lib", "site-packages")

# Limpar paths problemáticos do Hermes
sys.path = [p for p in sys.path if 'hermes' not in p.lower() and 'AppData/Local/hermes' not in p]

# Garantir que .venv_pipeline é o PRIMEIRO
if _VENV_SITE in sys.path:
    sys.path.remove(_VENV_SITE)
sys.path.insert(0, _VENV_SITE)
